"""Create an opt-in experimental engine DLL copy; never install or execute it.

Only the thin (32-byte entry) flex pool in one exact studiorender.dll build is
relocated. This is not a Bridge DLL patch. Modified output has not been game
validated, and its preserved original Authenticode signature is no longer valid.
"""
import argparse
import hashlib
import json
from pathlib import Path
import struct


EXPECTED_SHA256 = "3f5f5b0f539e8ad22bcfc4381be41571257c0c29e8061057682f9b8525ca7b85"
EXPECTED_TIMESTAMP = 0x6A440DD6
OLD_IMAGE_SIZE = 0x453000
NEW_POOL_RVA = OLD_IMAGE_SIZE
CACHE_RVA = 0xB2940
ENTRY_SIZE = 32
ENTRY_COUNT = 65536
POOL_SIZE = ENTRY_SIZE * ENTRY_COUNT
ADD_RVAS = (0x10CD, 0x540B, 0xDED1, 0x11083, 0x112D7)
CERTIFICATES = (
    (0x95600, 0x2C98, "859cfcd52bdaed18440376f4c50fa8277a8958664f7404d5fbe1c6b08afa6bc9"),
    (0x98298, 0x2C98, "d8d96d4de552931f312d6587e0a6d6404f670da835af225d0800b6a098812c04"),
)
WARNING = (
    "EXPERIMENTAL ENGINE PATCH: this is not a Bridge DLL; not yet game validated. "
    "The modified copy's original Authenticode signature is no longer valid. "
    "Original certificate/overlay bytes are preserved; no files are installed."
)


def _require(condition, message):
    if not condition:
        raise ValueError(message)


def _sha256(data):
    return hashlib.sha256(data).hexdigest()


def _read_pe(data):
    _require(len(data) >= 0x40 and data[:2] == b"MZ", "Not a DOS/PE image")
    pe = struct.unpack_from("<I", data, 0x3C)[0]
    _require(pe + 24 <= len(data) and data[pe:pe + 4] == b"PE\0\0", "Invalid PE header")
    machine, count, stamp, symbols, symbol_count, optional_size, flags = struct.unpack_from("<HHIIIHH", data, pe + 4)
    _require((machine, count, stamp, optional_size) == (0x14C, 4, EXPECTED_TIMESTAMP, 224), "Unexpected x86 PE build/layout")
    _require(symbols == symbol_count == 0 and flags & 0x2000, "Unexpected COFF symbols or non-DLL image")
    optional = pe + 24
    section_table = optional + optional_size
    _require(section_table + (count + 1) * 40 <= len(data), "Truncated section table")
    _require(struct.unpack_from("<H", data, optional)[0] == 0x10B, "Expected PE32 image")
    section_align, file_align = struct.unpack_from("<II", data, optional + 32)
    image_size, headers_size = struct.unpack_from("<II", data, optional + 56)
    _require((section_align, file_align, image_size, headers_size) == (0x1000, 0x200, OLD_IMAGE_SIZE, 0x400), "Unexpected PE alignment or image size")
    _require(struct.unpack_from("<I", data, optional + 92)[0] == 16, "Unexpected PE data directories")
    security_offset = optional + 96 + 4 * 8
    _require(struct.unpack_from("<II", data, security_offset) == CERTIFICATES[1][:2], "Unexpected certificate directory")
    sections = []
    for index in range(count):
        offset = section_table + index * 40
        name, size, rva, raw_size, raw_offset, relocations, line_numbers, reloc_count, line_count, characteristics = struct.unpack_from("<8sIIIIIIHHI", data, offset)
        _require(raw_offset % file_align == raw_size % file_align == rva % section_align == 0, "Misaligned section")
        _require(raw_offset >= headers_size and raw_offset + raw_size <= len(data), "Invalid raw section extent")
        _require(rva + max(size, raw_size) <= OLD_IMAGE_SIZE, "Invalid virtual section extent")
        _require(relocations == line_numbers == reloc_count == line_count == 0, "Unexpected section relocation/debug pointers")
        sections.append((name.rstrip(b"\0"), size, rva, raw_size, raw_offset, characteristics))
    _require([s[0] for s in sections] == [b".text", b".rdata", b".data", b".reloc"], "Unexpected section names/order")
    _require(min(s[4] for s in sections) == headers_size, "Unexpected first raw section")
    for previous, current in zip(sections, sections[1:]):
        _require(previous[4] + previous[3] == current[4], "Unexpected section gap/overlap")
        _require(previous[2] + max(previous[1], previous[3]) <= current[2], "Overlapping virtual sections")
    new_header = section_table + count * 40
    _require(new_header == 0x280 and new_header + 40 <= headers_size, "No expected spare section header")
    _require(data[new_header:new_header + 40] == bytes(40), "Spare section header is not empty")
    _require(max(s[4] + s[3] for s in sections) == CERTIFICATES[0][0], "Unexpected overlay start")
    _require(len(data) == CERTIFICATES[-1][0] + CERTIFICATES[-1][1], "Unexpected overlay/file length")
    for offset, size, digest in CERTIFICATES:
        block = data[offset:offset + size]
        _require(struct.unpack_from("<IHH", block) == (size, 0x200, 2), "Unexpected WIN_CERTIFICATE layout")
        _require(_sha256(block) == digest, "Unknown certificate/overlay bytes")
    return {"pe": pe, "optional": optional, "new_header": new_header, "sections": sections, "security_offset": security_offset}


def _rva_offset(pe, rva, size):
    for name, virtual_size, section_rva, raw_size, raw_offset, characteristics in pe["sections"]:
        delta = rva - section_rva
        if 0 <= delta and delta + size <= raw_size:
            _require(characteristics & 0x20000000, "Patch site is not executable")
            return raw_offset + delta
    raise ValueError(f"RVA 0x{rva:x} is not backed by file bytes")


def _pe_checksum(data, checksum_offset):
    checksum = 0
    for offset in range(0, len(data), 2):
        if checksum_offset <= offset < checksum_offset + 4:
            continue
        word = data[offset] | ((data[offset + 1] if offset + 1 < len(data) else 0) << 8)
        checksum += word
        checksum = (checksum & 0xFFFF) + (checksum >> 16)
    checksum = (checksum & 0xFFFF) + (checksum >> 16)
    return checksum + len(data)


def patch_image(original, *, experimental_engine_patch=False):
    _require(experimental_engine_patch, "Explicit --experimental-engine-patch opt-in is required")
    _require(_sha256(original) == EXPECTED_SHA256, "Unsupported input SHA256; only the pinned original DLL is accepted")
    pe = _read_pe(original)
    limit_offset = _rva_offset(pe, 0x1083, 10)
    _require(original[limit_offset:limit_offset + 10] == bytes.fromhex("81b93453070010270000"), "Unexpected thin-pool limit instruction")
    add_offsets = []
    for rva in ADD_RVAS:
        offset = _rva_offset(pe, rva, 5)
        _require(original[offset:offset + 5] == bytes.fromhex("059a3a0000"), f"Unexpected thin-pool address instruction at RVA 0x{rva:x}")
        add_offsets.append(offset)
    _require((NEW_POOL_RVA - CACHE_RVA) % ENTRY_SIZE == 0, "Pool is not cache-relative entry aligned")
    new_index = (NEW_POOL_RVA - CACHE_RVA) // ENTRY_SIZE
    output = bytearray(original)
    changes = []

    def edit(label, offset, replacement):
        before = bytes(output[offset:offset + len(replacement)])
        _require(len(before) == len(replacement), "Edit exceeds input extent")
        for previous in changes:
            start, end = previous["file_offset"], previous["file_offset"] + previous["length"]
            _require(offset + len(replacement) <= start or offset >= end, "Overlapping edits")
        output[offset:offset + len(replacement)] = replacement
        changes.append({"label": label, "file_offset": offset, "length": len(replacement), "before_hex": before.hex(), "after_hex": replacement.hex()})

    edit("thin pool limit: 10000 to 65536", limit_offset + 6, struct.pack("<I", ENTRY_COUNT))
    for rva, offset in zip(ADD_RVAS, add_offsets):
        edit(f"thin pool address at RVA 0x{rva:x}", offset + 1, struct.pack("<I", new_index))
    edit("NumberOfSections", pe["pe"] + 6, struct.pack("<H", 5))
    uninitialized = struct.unpack_from("<I", original, pe["optional"] + 12)[0]
    _require(uninitialized <= 0xFFFFFFFF - POOL_SIZE, "Uninitialized size would overflow")
    edit("SizeOfUninitializedData", pe["optional"] + 12, struct.pack("<I", uninitialized + POOL_SIZE))
    edit("SizeOfImage", pe["optional"] + 56, struct.pack("<I", NEW_POOL_RVA + POOL_SIZE))
    # Zero raw size/pointer gives a loader-zeroed pool without adding file bytes.
    # 0xc0000080 is uninitialized readable/writable data, never executable.
    header = struct.pack("<8sIIIIIIHHI", b".cflex\0\0", POOL_SIZE, NEW_POOL_RVA, 0, 0, 0, 0, 0, 0, 0xC0000080)
    edit(".cflex zero-filled RW section", pe["new_header"], header)
    checksum_offset = pe["optional"] + 64
    edit("PE CheckSum (not an Authenticode signature)", checksum_offset, struct.pack("<I", _pe_checksum(output, checksum_offset)))
    _require(output[CERTIFICATES[0][0]:] == original[CERTIFICATES[0][0]:], "Certificate/overlay preservation failed")
    security = pe["security_offset"]
    _require(output[security:security + 8] == original[security:security + 8], "Security directory preservation failed")
    result = bytes(output)
    manifest = {
        "format_version": 1,
        "warning": WARNING,
        "scope": "Thin flex pool only; 32-byte entries; legal indices 0..65535; no Bridge or game installation changes",
        "original_sha256": _sha256(original),
        "output_sha256": _sha256(result),
        "original_size": len(original),
        "output_size": len(result),
        "pe_timestamp": EXPECTED_TIMESTAMP,
        "pool_rva": NEW_POOL_RVA,
        "pool_entries": ENTRY_COUNT,
        "pool_entry_bytes": ENTRY_SIZE,
        "cache_relative_entry_offset": new_index,
        "authenticode_signature_valid_after_patch": False,
        "certificate_and_overlay_bytes_preserved": True,
        "game_validated": False,
        "changes": sorted(changes, key=lambda change: change["file_offset"]),
    }
    return result, manifest


def create_copy(source, output, manifest_path, *, experimental_engine_patch=False):
    source, output, manifest_path = map(Path, (source, output, manifest_path))
    _require(len({source.resolve(), output.resolve(), manifest_path.resolve()}) == 3, "Input, output and manifest paths must be distinct")
    for target in (output, manifest_path):
        if target.exists():
            raise FileExistsError(f"Refusing to overwrite existing file: {target}")
    result, manifest = patch_image(source.read_bytes(), experimental_engine_patch=experimental_engine_patch)
    # Exclusive creation also rejects files/symlinks appearing after the checks.
    created_output = created_manifest = False
    try:
        with output.open("xb") as handle:
            created_output = True
            with manifest_path.open("x", encoding="utf-8", newline="\n") as metadata:
                created_manifest = True
                handle.write(result)
                json.dump(manifest, metadata, ensure_ascii=False, indent=2)
                metadata.write("\n")
    except BaseException:
        if created_output:
            output.unlink()
        if created_manifest:
            manifest_path.unlink()
        raise
    return manifest


def verify_copy(source, output, manifest_path):
    expected, manifest = patch_image(Path(source).read_bytes(), experimental_engine_patch=True)
    _require(Path(output).read_bytes() == expected, "Output bytes differ from the exact expected experimental patch")
    _require(json.loads(Path(manifest_path).read_text(encoding="utf-8")) == manifest, "Manifest differs from the recomputed patch record")
    return manifest


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    commands = parser.add_subparsers(dest="command", required=True)
    create = commands.add_parser("create", help="Create a separate experimental copy and manifest, without installation")
    create.add_argument("input", type=Path)
    create.add_argument("output", type=Path)
    create.add_argument("--manifest", type=Path)
    create.add_argument("--experimental-engine-patch", action="store_true", required=True)
    verify = commands.add_parser("verify", help="Recompute and compare an existing copy and manifest")
    verify.add_argument("input", type=Path)
    verify.add_argument("output", type=Path)
    verify.add_argument("manifest", type=Path)
    args = parser.parse_args()
    try:
        if args.command == "create":
            manifest_path = args.manifest or args.output.with_name(args.output.name + ".manifest.json")
            manifest = create_copy(args.input, args.output, manifest_path, experimental_engine_patch=args.experimental_engine_patch)
        else:
            manifest = verify_copy(args.input, args.output, args.manifest)
    except (OSError, ValueError, struct.error) as error:
        parser.exit(1, f"Rejected: {error}\n")
    print(WARNING)
    print(f"{args.command}: SHA256 {manifest['output_sha256']}")


if __name__ == "__main__":
    main()
